import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana', 'Ben Arous', 'Mahdia'];
const NIVEAUX_STUDENT = ['Primaire', 'Collège', 'Lycée 1ère', 'Lycée 2ème', 'Lycée 3ème (Bac)', 'Université'];

const MODES = [
  { value: 'en_ligne',    label: '🌐 En ligne',         desc: 'Cours via Zoom, Meet...' },
  { value: 'presentiel',  label: '🏫 Présentiel',        desc: 'Cours en face à face' },
  { value: 'les_deux',    label: '🔀 Les deux',          desc: 'En ligne et présentiel' },
];

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    niveau: '', tarifs_matieres: [], certificats: [], photo_url: null,
    mode_enseignement: 'presentiel',
    tarif_en_ligne: '',
    tarif_presentiel: '',
  });
  const [structure, setStructure] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);
  const [showCertModal, setShowCertModal] = useState(false);
  const [newCert, setNewCert] = useState({ titre: '', description: '' });
  const [selectedFile, setSelectedFile] = useState(null);

  useEffect(() => { fetchProfileData(); }, [user]);

  const fetchProfileData = async () => {
    try {
      let route = '';
      if (user?.role === 'professeur') route = '/api/professeurs/me';
      else if (user?.role === 'étudiant') route = '/api/etudiants/me';
      else route = '/api/auth/me';

      const res = await api.get(route);
      const data = res.data;

      setForm(prev => ({
        ...prev,
        ...data,
        user_prenom: data.prenom || data.user_prenom || prev.user_prenom,
        user_nom: data.nom || data.user_nom || prev.user_nom,
        ville: data.ville || prev.ville,
        telephone: data.telephone || prev.telephone,
        bio: data.bio || prev.bio,
        niveau: data.niveau || prev.niveau,
        email: data.email || prev.email,
        certificats: data.certificats || prev.certificats,
        tarifs_matieres: data.tarifs_matieres || prev.tarifs_matieres,
        mode_enseignement: data.mode_enseignement || 'presentiel',
        tarif_en_ligne: data.tarif_en_ligne ?? '',
        tarif_presentiel: data.tarif_presentiel ?? '',
      }));

      if (user?.role === 'professeur') {
        const resStruct = await api.get('/api/admin/referentiel/structure');
        setStructure(resStruct.data);
      }
      setLoading(false);
    } catch (e) {
      console.error("Erreur chargement profil", e);
      setLoading(false);
    }
  };

  const handleInput = (key, val) => setForm({ ...form, [key]: val });

  const handlePhotoUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    try {
      const res = await api.post('/api/professeurs/me/photo', formData, { headers: { 'Content-Type': 'multipart/form-data' } });
      setForm({ ...form, photo_url: res.data.url });
      alert("✅ Photo de profil mise à jour !");
    } catch (e) { alert("Erreur photo"); }
  };

  const handleCertUpload = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('titre', newCert.titre);
    formData.append('file', selectedFile);
    try {
      await api.post('/api/professeurs/me/certificats', formData, { headers: { 'Content-Type': 'multipart/form-data' } });
      setShowCertModal(false); fetchProfileData();
    } catch (e) { alert("Erreur certificat"); }
  };

  const isSelected = (matId, nivId) => form.tarifs_matieres?.some(t => t.matiere_id === matId && t.niveau_id === nivId);
  const getTarif = (matId, nivId) => form.tarifs_matieres?.find(t => t.matiere_id === matId && t.niveau_id === nivId)?.tarif || '';

  const handleToggleMatiere = (matId, nivId) => {
    let list = [...(form.tarifs_matieres || [])];
    if (isSelected(matId, nivId)) list = list.filter(t => !(t.matiere_id === matId && t.niveau_id === nivId));
    else list.push({ matiere_id: matId, niveau_id: nivId, tarif: 20 });
    setForm({ ...form, tarifs_matieres: list });
  };

  const handlePriceChange = (matId, nivId, price) => {
    const updated = form.tarifs_matieres.map(t =>
      (t.matiere_id === matId && t.niveau_id === nivId) ? { ...t, tarif: parseFloat(price) || 0 } : t
    );
    setForm({ ...form, tarifs_matieres: updated });
  };

  async function handleSave() {
    try {
      let route = '';
      if (user?.role === 'professeur') route = '/api/professeurs/me';
      else if (user?.role === 'étudiant') route = '/api/etudiants/me';
      else route = '/api/auth/me';

      await api.put(route, {
        nom: form.user_nom, prenom: form.user_prenom, ville: form.ville,
        telephone: form.telephone, bio: form.bio,
        ...(user?.role === 'professeur' && {
          tarifs_complets: form.tarifs_matieres,
          mode_enseignement: form.mode_enseignement,
          tarif_en_ligne: form.tarif_en_ligne !== '' ? parseFloat(form.tarif_en_ligne) : null,
          tarif_presentiel: form.tarif_presentiel !== '' ? parseFloat(form.tarif_presentiel) : null,
        }),
        ...(user?.role === 'étudiant' && { niveau: form.niveau })
      });
      setSaved(true); setTimeout(() => setSaved(false), 2000);
      alert("✅ Profil enregistré !");
    } catch (e) { alert('Erreur sauvegarde'); }
  }

  const inp = {
    background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10,
    color: 'var(--text)', padding: '10px 14px', fontSize: '.9rem', width: '100%',
    outline: 'none', marginBottom: '15px'
  };

  if (loading) return <div style={{ padding: 50, textAlign: 'center' }}>Chargement du profil...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>

      {/* HEADER PHOTO */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 30, marginBottom: 32, background: 'var(--card)', padding: 24, borderRadius: 24, border: '1px solid var(--border)' }}>
        <div style={{ position: 'relative' }}>
          <div style={{ width: 110, height: 110, borderRadius: '50%', overflow: 'hidden', border: '3px solid var(--accent)', background: 'var(--surface2)' }}>
            <img src={form.photo_url ? `http://localhost:8001${form.photo_url}` : 'https://ui-avatars.com/api/?name=' + form.user_prenom} alt="Avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          </div>
          {user?.role === 'professeur' && (
            <label style={{ position: 'absolute', bottom: 5, right: 5, background: 'var(--accent)', width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', border: '2px solid var(--card)' }}>
              📷 <input type="file" hidden onChange={handlePhotoUpload} />
            </label>
          )}
        </div>
        <div>
          <h2 style={{ fontFamily: 'Syne', fontSize: '1.8rem' }}>{form.user_prenom} {form.user_nom}</h2>
          <p style={{ color: 'var(--text2)', textTransform: 'capitalize' }}>Compte {user?.role}</p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: user?.role === 'professeur' ? '450px 1fr' : '1fr', gap: 30 }}>

        {/* COLONNE GAUCHE */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>

          {/* IDENTITÉ */}
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20 }}>👤 Mon Identité</h3>
            <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Prénom</label>
            <input style={inp} value={form.user_prenom} onChange={e => handleInput('user_prenom', e.target.value)} />
            <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Nom</label>
            <input style={inp} value={form.user_nom} onChange={e => handleInput('user_nom', e.target.value)} />
            <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Email</label>
            <input style={{ ...inp, opacity: 0.6 }} value={form.email} readOnly />

            {user?.role === 'étudiant' && (
              <>
                <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Niveau</label>
                <select style={inp} value={form.niveau} onChange={e => handleInput('niveau', e.target.value)}>
                  <option value="">Sélectionner...</option>
                  {NIVEAUX_STUDENT.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </>
            )}

            {user?.role !== 'admin' && (
              <>
                <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Téléphone</label>
                <input style={inp} value={form.telephone} onChange={e => handleInput('telephone', e.target.value)} />
                <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Ville</label>
                <select style={inp} value={form.ville} onChange={e => handleInput('ville', e.target.value)}>
                  {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </>
            )}
            <button onClick={handleSave} style={{ width: '100%', background: 'var(--accent)', color: '#fff', border: 'none', padding: 14, borderRadius: 12, fontWeight: 600, cursor: 'pointer' }}>
              {saved ? '✅ Enregistré !' : 'Enregistrer'}
            </button>
          </div>

          {/* BIO */}
          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginBottom: 15 }}>📝 Ma Bio / Méthodologie</h3>
              <textarea
                style={{ ...inp, height: 150, resize: 'none', padding: '15px' }}
                value={form.bio || ''}
                placeholder="Ex: Professeur diplômé avec 10 ans d'expérience..."
                onChange={e => handleInput('bio', e.target.value)}
              />
            </div>
          )}

          {/* ====== MODE D'ENSEIGNEMENT (NOUVEAU BLOC) ====== */}
          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginBottom: 6 }}>🎓 Mode d'enseignement</h3>
              <p style={{ fontSize: '.8rem', color: 'var(--text2)', marginBottom: 18 }}>
                Choisissez comment vous donnez vos cours, puis précisez votre tarif horaire.
              </p>

              {/* Sélection du mode */}
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginBottom: 20 }}>
                {MODES.map(m => {
                  const active = form.mode_enseignement === m.value;
                  return (
                    <div
                      key={m.value}
                      onClick={() => handleInput('mode_enseignement', m.value)}
                      style={{
                        display: 'flex', alignItems: 'center', gap: 14,
                        padding: '14px 18px', borderRadius: 14, cursor: 'pointer',
                        border: active ? '2px solid var(--accent)' : '2px solid var(--border)',
                        background: active ? 'rgba(108,99,255,0.1)' : 'var(--surface2)',
                        transition: 'all .2s',
                      }}
                    >
                      <div style={{
                        width: 20, height: 20, borderRadius: '50%',
                        border: `2px solid ${active ? 'var(--accent)' : 'var(--text2)'}`,
                        background: active ? 'var(--accent)' : 'transparent',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        flexShrink: 0,
                      }}>
                        {active && <div style={{ width: 8, height: 8, borderRadius: '50%', background: '#fff' }} />}
                      </div>
                      <div>
                        <div style={{ fontWeight: 700, fontSize: '.9rem', color: active ? 'var(--accent)' : 'var(--text)' }}>
                          {m.label}
                        </div>
                        <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>{m.desc}</div>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Tarifs conditionnels */}
              {form.mode_enseignement === 'en_ligne' && (
                <div style={{ background: 'rgba(56,189,248,0.07)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 12, padding: 16 }}>
                  <label style={{ fontSize: '.8rem', color: '#38bdf8', fontWeight: 600, display: 'block', marginBottom: 8 }}>
                    🌐 Tarif en ligne (DT/heure)
                  </label>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <input
                      type="number" min="0" step="0.5"
                      style={{ ...inp, marginBottom: 0, flex: 1 }}
                      placeholder="Ex: 30"
                      value={form.tarif_en_ligne}
                      onChange={e => handleInput('tarif_en_ligne', e.target.value)}
                    />
                    <span style={{ color: 'var(--text2)', fontWeight: 600, whiteSpace: 'nowrap' }}>DT / h</span>
                  </div>
                </div>
              )}

              {form.mode_enseignement === 'presentiel' && (
                <div style={{ background: 'rgba(67,233,123,0.07)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 12, padding: 16 }}>
                  <label style={{ fontSize: '.8rem', color: '#43e97b', fontWeight: 600, display: 'block', marginBottom: 8 }}>
                    🏫 Tarif présentiel (DT/heure)
                  </label>
                  <p style={{ fontSize: '.75rem', color: 'var(--text2)', marginBottom: 10 }}>
                    Vous pouvez fixer votre prix ou le laisser négociable avec l'étudiant.
                  </p>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <input
                      type="number" min="0" step="0.5"
                      style={{ ...inp, marginBottom: 0, flex: 1 }}
                      placeholder="Ex: 40"
                      value={form.tarif_presentiel}
                      onChange={e => handleInput('tarif_presentiel', e.target.value)}
                    />
                    <span style={{ color: 'var(--text2)', fontWeight: 600, whiteSpace: 'nowrap' }}>DT / h</span>
                  </div>
                </div>
              )}

              {form.mode_enseignement === 'les_deux' && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                  <div style={{ background: 'rgba(56,189,248,0.07)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 12, padding: 16 }}>
                    <label style={{ fontSize: '.8rem', color: '#38bdf8', fontWeight: 600, display: 'block', marginBottom: 8 }}>
                      🌐 Tarif en ligne (DT/heure)
                    </label>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                      <input
                        type="number" min="0" step="0.5"
                        style={{ ...inp, marginBottom: 0, flex: 1 }}
                        placeholder="Ex: 30"
                        value={form.tarif_en_ligne}
                        onChange={e => handleInput('tarif_en_ligne', e.target.value)}
                      />
                      <span style={{ color: 'var(--text2)', fontWeight: 600, whiteSpace: 'nowrap' }}>DT / h</span>
                    </div>
                  </div>
                  <div style={{ background: 'rgba(67,233,123,0.07)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 12, padding: 16 }}>
                    <label style={{ fontSize: '.8rem', color: '#43e97b', fontWeight: 600, display: 'block', marginBottom: 8 }}>
                      🏫 Tarif présentiel (DT/heure)
                    </label>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                      <input
                        type="number" min="0" step="0.5"
                        style={{ ...inp, marginBottom: 0, flex: 1 }}
                        placeholder="Ex: 40"
                        value={form.tarif_presentiel}
                        onChange={e => handleInput('tarif_presentiel', e.target.value)}
                      />
                      <span style={{ color: 'var(--text2)', fontWeight: 600, whiteSpace: 'nowrap' }}>DT / h</span>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}
          {/* ====== FIN MODE D'ENSEIGNEMENT ====== */}

          {/* DIPLÔMES */}
          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginBottom: 15 }}>📜 Mes Diplômes</h3>
              <div style={{ display: 'grid', gap: 10, marginBottom: 15 }}>
                {form.certificats?.map(c => (
                  <div key={c.id} style={{ background: 'var(--surface2)', padding: 12, borderRadius: 12, border: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ fontWeight: 600, fontSize: '.85rem' }}>{c.titre}</span>
                    <a href={`http://localhost:8001${c.fichier_url}`} target="_blank" rel="noreferrer" style={{ color: 'var(--accent)' }}>👁️</a>
                  </div>
                ))}
              </div>
              <button onClick={() => setShowCertModal(true)} style={{ width: '100%', border: '2px dashed var(--border)', background: 'none', color: 'var(--accent)', padding: 15, borderRadius: 12, cursor: 'pointer' }}>
                + Ajouter un diplôme
              </button>
            </div>
          )}
        </div>

        {/* COLONNE DROITE : TARIFS PAR MATIÈRE */}
        {user?.role === 'professeur' && (
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20 }}>📚 Mes Enseignements & Tarifs</h3>
            {structure.map(dom => (
              <div key={dom.id} style={{ marginBottom: 35 }}>
                <div style={{ color: 'var(--accent)', fontWeight: 800, fontSize: '1.1rem', marginBottom: 15, borderBottom: '2px solid var(--accent)', paddingBottom: 5 }}>
                  📂 {dom.nom.toUpperCase()}
                </div>
                {dom.niveaux?.map(niv => (
                  <div key={niv.id} style={{ marginLeft: 15, marginBottom: 25, background: 'var(--surface2)', padding: 20, borderRadius: 20, border: '1px solid var(--border)' }}>
                    <div style={{ fontWeight: 700, fontSize: '1rem', marginBottom: 15 }}>🎓 {niv.nom}</div>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                      {niv.matieres?.map(mat => {
                        const active = isSelected(mat.id, niv.id);
                        return (
                          <div key={mat.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: active ? 'rgba(108,99,255,0.08)' : 'var(--card)', padding: '10px 15px', borderRadius: 12, border: active ? '1px solid var(--accent)' : '1px solid transparent' }}>
                            <label style={{ fontSize: '.85rem', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 10 }}>
                              <input type="checkbox" checked={active} onChange={() => handleToggleMatiere(mat.id, niv.id)} />
                              {mat.nom}
                            </label>
                            {active && (
                              <input
                                type="number"
                                value={getTarif(mat.id, niv.id)}
                                onChange={e => handlePriceChange(mat.id, niv.id, e.target.value)}
                                style={{ width: 55, background: 'var(--bg)', color: '#fff', border: 'none', textAlign: 'center', borderRadius: 8, padding: '4px' }}
                              />
                            )}
                          </div>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* MODALE DIPLÔME */}
      {showCertModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ background: 'var(--surface)', padding: 35, borderRadius: 25, width: 450, border: '1px solid var(--border)' }}>
            <h3 style={{ marginBottom: 20 }}>📁 Nouveau Diplôme</h3>
            <form onSubmit={handleCertUpload} style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
              <input style={inp} placeholder="Titre (ex: Master en Informatique)" onChange={e => setNewCert({ ...newCert, titre: e.target.value })} required />
              <input type="file" onChange={e => setSelectedFile(e.target.files[0])} required />
              <div style={{ display: 'flex', gap: 12 }}>
                <button type="submit" style={{ flex: 2, background: 'var(--accent)', color: '#fff', padding: 12, borderRadius: 12, border: 'none', fontWeight: 700 }}>Sauvegarder</button>
                <button type="button" onClick={() => setShowCertModal(false)} style={{ flex: 1, background: 'var(--surface2)', color: '#fff', padding: 12, borderRadius: 12, border: 'none' }}>Annuler</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
